289| /// Split a user-supplied target into a repository root and an explicit config
290| /// path.
291| ///
292| /// `check path/to/file.toml` should validate that file while still resolving
293| /// presets relative to the repository it sits in, so a file target contributes
294| /// both halves.
295| fn split_target(path: &Path) -> (std::path::PathBuf, Option<std::path::PathBuf>) {
296|     if path.is_file() {
297|         let root = path
298|             .parent()
299|             .filter(|p| !p.as_os_str().is_empty())
300|             .map(Path::to_path_buf)
301|             .unwrap_or_else(|| std::path::PathBuf::from("."));
302|         // A config discovered inside .github/ belongs to the repository above
303|         // it, not to .github/ — otherwise presets would never be found.
304|         let root = if root.file_name().map(|n| n == ".github").unwrap_or(false) {
305|             root.parent().map(Path::to_path_buf).unwrap_or(root)
306|         } else {
307|             root
308|         };
309|         (root, Some(path.to_path_buf()))
310|     } else {
311|         (path.to_path_buf(), None)
312|     }
313| }
