747| /// Publish scanner findings whose owning lane never ran.
748| ///
749| /// The owner is decided by kind: `security` adjudicates workflow and dependency
750| /// matches, `commits` adjudicates secrets, blobs and junk. When the owner ran it
751| /// has already republished them verbatim, and doing it again here would report
752| /// the same committed key twice.
753| fn publish_unclaimed(lanes: &mut Vec<LaneProposal>, scan_findings: &[scan::types::Finding]) {
754|     for owner in [LaneId::Security, LaneId::Commits] {
755|         let ran = lanes
756|             .iter()
757|             .any(|l| l.lane == owner && l.conclusion != CheckConclusion::Neutral);
758|         if ran {
759|             continue;
760|         }
761| 
762|         let kinds: &[ScanKind] = match owner {
763|             LaneId::Security => &lanes::security::ADJUDICATES,
764|             _ => &lanes::commits::ADJUDICATES,
765|         };
766| 
767|         // Only findings that would block. A low-severity junk file is not worth
768|         // failing a check nobody's lane was asked to look at.
769|         let unclaimed: Vec<Finding> = scan_findings
770|             .iter()
771|             .filter(|f| kinds.contains(&f.kind) && f.severity >= Severity::High)
772|             .cloned()
773|             .map(|scan| {
774|                 let mut finding = Finding::from(scan);
775|                 finding.lane = owner;
776|                 finding
777|             })
778|             .collect();
779| 
780|         if unclaimed.is_empty() {
781|             continue;
782|         }
783| 
784|         // Replace the Neutral placeholder rather than sitting beside it: two
785|         // check runs of the same name is a confusing way to fail.
786|         lanes.retain(|l| l.lane != owner);
787|         lanes.push(LaneProposal {
788|             lane: owner,
789|             check_name: owner.check_name(),
790|             conclusion: CheckConclusion::Failure,
791|             summary: format!(
792|                 "{} finding(s) from the deterministic scanners.",
793|                 unclaimed.len()
794|             ),
795|             findings: unclaimed,
796|             resolved: vec![],
797|             deduped: 0,
798|             highest_severity: Some(Severity::High),
799|             // Scanners are deterministic and offline: no model, no spend.
800|             usage: Usage::default(),
801|             models: vec![],
802|         });
803|     }
804| }
