806| /// The deterministic aggregate every other lane feeds.
807| fn gate(lanes: &[LaneProposal]) -> LaneProposal {
808|     let blocking: Vec<&LaneProposal> = lanes.iter().filter(|l| l.conclusion.blocks()).collect();
809| 
810|     let (conclusion, summary) = if blocking.is_empty() {
811|         (CheckConclusion::Success, "All lanes passed.".to_string())
812|     } else {
813|         (
814|             CheckConclusion::Failure,
815|             format!(
816|                 "Blocked by {}.",
817|                 blocking
818|                     .iter()
819|                     .map(|l| l.lane.as_str())
820|                     .collect::<Vec<_>>()
821|                     .join(", ")
822|             ),
823|         )
824|     };
825| 
826|     LaneProposal {
827|         lane: LaneId::Gate,
828|         check_name: LaneId::Gate.check_name(),
829|         conclusion,
830|         summary,
831|         findings: vec![],
832|         resolved: vec![],
833|         deduped: 0,
834|         highest_severity: None,
835|         // The gate is an aggregate of the other lanes; attributing their spend
836|         // to it as well would double-count every dollar in the summary.
837|         usage: Usage::default(),
838|         models: vec![],
839|     }
840| }
