852| fn reviewable_diffs(config: &Config, context: &PullRequestContext) -> Result<Vec<FileDiff>> {
853|     // Shared with the indexer's file selection: `paths.ignore` must mean the
854|     // same thing to both halves of the product, and two spellings of it would
855|     // be a config whose behaviour depended on which half was reading it.
856|     let ignored = crate::chunk::select::ignore_globs(&config.paths.ignore)?;
857| 
858|     let kept: Vec<_> = context
859|         .files
860|         .iter()
861|         .filter(|f| !ignored.is_match(&f.path))
862|         .cloned()
863|         .collect();
864| 
865|     Ok(parse_changed_files(&kept))
866| }
