868| fn run_scanners(
869|     config: &Config,
870|     diffs: &[FileDiff],
871|     context: &PullRequestContext,
872| ) -> Vec<scan::types::Finding> {
873|     let max_blob = config
874|         .lane(LaneId::Commits)
875|         .and_then(|l| l.max_blob_bytes)
876|         .unwrap_or(1024 * 1024);
877| 
878|     let mut findings = Vec::new();
879|     for diff in diffs {
880|         findings.extend(scan::secrets::scan_added_lines(
881|             &diff.path,
882|             diff.added_lines(),
883|         ));
884|         findings.extend(scan::workflows::scan_added_lines(
885|             &diff.path,
886|             diff.added_lines(),
887|         ));
888|     }
889|     findings.extend(scan::blobs::scan_files(&context.files, max_blob));
890|     findings
891| }
