 13| /// Build a repository skeleton with an optional config file and preset.
 14| fn repo(config: Option<&str>, presets: &[(&str, &str)]) -> TempDir {
 15|     let dir = tempfile::tempdir().expect("tempdir");
 16|     if let Some(text) = config {
 17|         std::fs::write(dir.path().join(".tinysweeper.toml"), text).expect("write config");
 18|     }
 19|     for (name, text) in presets {
 20|         let preset_dir = dir.path().join("presets").join(name);
 21|         std::fs::create_dir_all(&preset_dir).expect("create preset dir");
 22|         std::fs::write(preset_dir.join("preset.toml"), text).expect("write preset");
 23|     }
 24|     dir
 25| }
