 27| /// Write a rule document into a repository skeleton's `presets/rules/`.
 28| fn with_rules(dir: &TempDir, name: &str, text: &str) {
 29|     let rules_dir = dir.path().join("presets").join("rules");
 30|     std::fs::create_dir_all(&rules_dir).expect("create rules dir");
 31|     std::fs::write(rules_dir.join(format!("{name}.md")), text).expect("write rule document");
 32| }
