 34| /// Copy this repository's own rule documents into a skeleton, so a shipped
 35| /// preset that references one resolves.
 36| fn with_shipped_rules(dir: &TempDir) {
 37|     let source = Path::new(env!("CARGO_MANIFEST_DIR"))
 38|         .join("presets")
 39|         .join("rules");
 40|     for entry in std::fs::read_dir(&source).expect("read shipped rules") {
 41|         let entry = entry.expect("dir entry");
 42|         if entry.path().extension().is_some_and(|e| e == "md") {
 43|             let name = entry
 44|                 .path()
 45|                 .file_stem()
 46|                 .unwrap()
 47|                 .to_string_lossy()
 48|                 .into_owned();
 49|             with_rules(
 50|                 dir,
 51|                 &name,
 52|                 &std::fs::read_to_string(entry.path()).expect("read rule document"),
 53|             );
 54|         }
 55|     }
 56| }
