  1| //! Configuration validation.
  2| //!
  3| //! The rule here is that a single run reports **every** problem, not the first
  4| //! one. Someone fixing their config should need one round trip, not six — and
  5| //! in CI, where each round trip is a push and a wait, that difference is the
  6| //! whole experience.
  7| //!
  8| //! Messages name the key, say what is wrong, and say what would be right.
  9| 
 10| use globset::Glob;
 11| 
 12| use crate::config::types::{Config, LaneId, MergeMethod, ModelRef, Severity};
 13| 
 14| /// The maximum schema version this build understands.
 15| pub const SCHEMA_VERSION: u32 = 1;
 16| 
 17| /// Check `config`, returning every problem found.
 18| ///
 19| /// An empty vector means the config is usable. It does not mean the config is
 20| /// *sensible* — that is what `doctor` is for.
 21| pub fn validate(config: &Config) -> Vec<String> {
 22|     let mut problems = Vec::new();
 23| 
 24|     validate_version(config, &mut problems);
 25|     validate_review(config, &mut problems);
 26|     validate_paths(config, &mut problems);
 27|     validate_models(config, &mut problems);
 28|     validate_knowledge(config, &mut problems);
 29|     validate_embeddings(config, &mut problems);
 30|     validate_retrieval(config, &mut problems);
 31|     validate_lanes(config, &mut problems);
 32|     validate_automerge(config, &mut problems);
 33|     validate_issues(config, &mut problems);
 34|     validate_automation(config, &mut problems);
 35|     validate_sentry(config, &mut problems);
 36| 
 37|     problems
 38| }
 39| 
 40| fn validate_version(config: &Config, problems: &mut Vec<String>) {
 41|     if config.version == 0 {
 42|         problems.push("`version` is missing; set `version = 1`".into());
 43|     } else if config.version > SCHEMA_VERSION {
 44|         problems.push(format!(
 45|             "`version = {}` is newer than this build understands (max {SCHEMA_VERSION}); upgrade tinysweeper",
 46|             config.version
 47|         ));
 48|     }
 49| }
 50| 
 51| fn validate_review(config: &Config, problems: &mut Vec<String>) {
 52|     let review = &config.review;
 53| 
 54|     if review.lanes.is_empty() {
 55|         problems.push("`review.lanes` is empty; nothing would run".into());
 56|     }
 57|     for name in &review.lanes {
 58|         if LaneId::parse(name).is_none() {
 59|             problems.push(format!(
 60|                 "`review.lanes` contains unknown lane `{name}`; expected one of {}",
 61|                 known(&LaneId::ALL.map(|l| l.as_str()))
 62|             ));
 63|         }
 64|     }
 65|     // The gate is deterministic and always publishes; listing it is a sign
 66|     // someone thinks it is optional, which would be a nasty surprise when they
 67|     // remove it and branch protection keeps waiting for a check that never
 68|     // arrives.
 69|     if review
 70|         .lanes
 71|         .iter()
 72|         .any(|l| LaneId::parse(l) == Some(LaneId::Gate))
 73|     {
 74|         problems.push(
 75|             "`review.lanes` lists `gate`; the gate is deterministic and always runs, so remove it"
 76|                 .into(),
 77|         );
 78|     }
 79| 
