166| /// or a full `diff --git` stanza, so the same parser serves the forge adapter
167| /// and `git diff` output.
168| pub fn parse_file_patch(path: &str, patch: &str) -> FileDiff {
169|     let mut diff = FileDiff {
170|         path: path.to_string(),
171|         ..FileDiff::default()
172|     };
173| 
174|     let mut current: Option<Hunk> = None;
175|     let mut new_line = 0u64;
176|     let mut old_line = 0u64;
177| 
178|     for raw in patch.lines() {
179|         if raw.starts_with("@@") {
180|             if let Some(hunk) = current.take() {
181|                 diff.hunks.push(hunk);
182|             }
183|             match parse_hunk_header(raw) {
184|                 Some(header) => {
185|                     new_line = header.new_start;
186|                     old_line = header.old_start;
187|                     current = Some(header);
188|                 }
189|                 // A malformed header means we no longer know where we are, so
190|                 // stop attributing lines rather than guess and mis-anchor.
191|                 None => current = None,
192|             }
193|             continue;
194|         }
195| 
196|         // Headers only appear *between* hunks. Inside one, `--- foo` is a
197|         // removed line whose content happens to start with `--`, and treating
198|         // it as a header drops it — desynchronising every line number after it,
199|         // which is the one thing this parser must never do.
200|         if current.is_none()
201|             && (raw.starts_with("diff --git")
202|                 || raw.starts_with("index ")
203|                 || raw.starts_with("--- ")
204|                 || raw.starts_with("+++ "))
205|         {
206|             continue;
207|         }
208| 
209|         let Some(hunk) = current.as_mut() else {
210|             continue;
211|         };
212| 
213|         let (kind, text) = match raw.as_bytes().first() {
214|             Some(b'+') => (LineKind::Added, &raw[1..]),
215|             Some(b'-') => (LineKind::Removed, &raw[1..]),
216|             Some(b' ') => (LineKind::Context, &raw[1..]),
217|             // "\ No newline at end of file" carries no line of its own.
218|             Some(b'\\') => continue,
219|             // An empty line inside a hunk is a context line whose single space
220|             // some tools strip.
221|             None => (LineKind::Context, ""),
222|             _ => continue,
223|         };
224| 
225|         match kind {
226|             LineKind::Added => {
227|                 hunk.lines.push(DiffLine {
228|                     kind,
229|                     new_line: Some(new_line),
230|                     old_line: None,
231|                     text: text.to_string(),
232|                 });
233|                 diff.changed_lines.insert(new_line);
234|                 new_line += 1;
235|             }
236|             LineKind::Removed => {
237|                 hunk.lines.push(DiffLine {
238|                     kind,
239|                     new_line: None,
240|                     old_line: Some(old_line),
241|                     text: text.to_string(),
242|                 });
243|                 old_line += 1;
244|             }
245|             LineKind::Context => {
246|                 hunk.lines.push(DiffLine {
247|                     kind,
248|                     new_line: Some(new_line),
249|                     old_line: Some(old_line),
250|                     text: text.to_string(),
251|                 });
252|                 new_line += 1;
253|                 old_line += 1;
254|             }
255|         }
256|     }
257| 
258|     if let Some(hunk) = current.take() {
259|         diff.hunks.push(hunk);
260|     }
261| 
262|     diff
263| }
