299|                 hunk.old_start, hunk.old_lines, hunk.new_start, hunk.new_lines
300|             );
301|             for line in &hunk.lines {
302|                 let marker = match line.kind {
303|                     LineKind::Added => '+',
304|                     LineKind::Removed => '-',
305|                     LineKind::Context => ' ',
306|                 };
307|                 match line.new_line {
308|                     Some(n) => {
309|                         let _ = writeln!(out, "{n:>5} {marker}{}", line.text);
310|                     }
311|                     None => {
312|                         let _ = writeln!(out, "      {marker}{}", line.text);
