321| fn parse_hunk_header(line: &str) -> Option<Hunk> {
322|     // @@ -old_start,old_lines +new_start,new_lines @@ optional heading
323|     let body = line.strip_prefix("@@")?;
324|     let end = body.find("@@")?;
325|     let ranges = &body[..end];
326|     let heading = body[end + 2..].trim().to_string();
327| 
328|     let mut old = None;
329|     let mut new = None;
330|     for token in ranges.split_whitespace() {
331|         if let Some(rest) = token.strip_prefix('-') {
332|             old = parse_range(rest);
333|         } else if let Some(rest) = token.strip_prefix('+') {
334|             new = parse_range(rest);
335|         }
336|     }
337| 
338|     let (old_start, old_lines) = old?;
339|     let (new_start, new_lines) = new?;
340| 
341|     Some(Hunk {
342|         old_start,
343|         old_lines,
344|         new_start,
345|         new_lines,
346|         heading,
347|         lines: Vec::new(),
348|     })
349| }
