 29|     for diff in diffs {
 30|         if diff.hunks.is_empty() {
 31|             continue;
 32|         }
 33|         out.push_str(&format!("{FILE_PREFIX}{}\n", diff.path));
 34|         for hunk in &diff.hunks {
 35|             out.push_str(&format!(
 36|                 "@@ -{},{} +{},{} @@\n",
 37|                 hunk.old_start, hunk.old_lines, hunk.new_start, hunk.new_lines
 38|             ));
 39|             for line in &hunk.lines {
 40|                 let marker = match line.kind {
 41|                     LineKind::Added => '+',
 42|                     LineKind::Removed => '-',
 43|                     LineKind::Context => ' ',
 44|                 };
 45|                 match line.new_line {
 46|                     Some(n) => out.push_str(&format!("{n:>5} {marker}{}\n", line.text)),
 47|                     None => out.push_str(&format!("      {marker}{}\n", line.text)),
 48|                 }
 49|             }
 50|         }
 51|     }
 52|     out
 53| }
