  1| //! The code a finding's identity is computed over.
  2| //!
  3| //! [`Finding::fingerprint`](crate::findings::Finding::fingerprint) hashes the
  4| //! lane, the path, the rule and a *snippet of the code* — deliberately not the
  5| //! line number, the severity or the prose. Producing that snippet needs the
  6| //! parsed diff, which the apply path does not have, so it happens once during
  7| //! review and the result travels in the proposal.
  8| //!
  9| //! This is the difference between dedupe that holds across pushes and dedupe
 10| //! that does not: the fingerprint written into the `tinysweeper:fp=` marker
 11| //! used to be taken over the finding's *title*, so a model rewording its own
 12| //! sentence minted a fresh identity and the comment was posted again.
 13| 
 14| use crate::evidence::diff::FileDiff;
 15| use crate::findings::types::Finding;
 16| 
 17| /// The changed-line text `finding` anchors to, as the fingerprint sees it.
 18| ///
 19| /// Empty when the finding names no line, or names a file the diff no longer
 20| /// contains. Empty is a usable identity rather than a failure: the fingerprint
 21| /// still covers the lane, the path and the rule, so two findings only collide
 22| /// when they are genuinely the same rule on the same file with no anchor to
 23| /// tell them apart.
 24| pub fn anchor_context(finding: &Finding, diffs: &[FileDiff]) -> String {
 25|     let Some((start, end)) = finding.range() else {
 26|         return String::new();
 27|     };
 28|     let Some(diff) = diffs.iter().find(|d| d.path == finding.path) else {
 29|         return String::new();
 30|     };
 31| 
 32|     let mut lines = Vec::new();
 33|     for hunk in &diff.hunks {
 34|         for line in &hunk.lines {
 35|             if let Some(number) = line.new_line
 36|                 && (start..=end).contains(&number)
 37|             {
 38|                 lines.push(line.text.as_str());
 39|             }
 40|         }
 41|     }
 42|     lines.join("\n")
 43| }
 44| 
 45| /// Stamp every finding with the identity dedupe and triage key on.
 46| ///
 47| /// Done in one place so review, apply and the dedupe reader cannot disagree
 48| /// about what a finding *is*.
 49| pub fn stamp(findings: &mut [Finding], diffs: &[FileDiff]) {
 50|     for finding in findings.iter_mut() {
 51|         let context = anchor_context(finding, diffs);
 52|         finding.identity = Some(finding.fingerprint(&context));
 53|     }
 54| }
 55| 
