 7| /// Shorten `text` to at most `limit` characters, ending on a word boundary.
 8| ///
 9| /// Used for check-run titles, where GitHub imposes its own ceiling and a title
10| /// cut mid-word reads worse than one that stops early.
11| pub fn shorten(text: &str, limit: usize) -> String {
12|     let text = text.trim();
13|     if text.chars().count() <= limit {
14|         return text.to_string();
15|     }
16| 
