  1| //! Wire-format tests for the OpenRouter embeddings client.
  2| //!
  3| //! These are offline. They exercise the part that goes wrong quietly — reading
  4| //! the response — rather than the part that goes wrong loudly. A malformed
  5| //! request fails on the first call and somebody notices; a response decoded in
  6| //! the wrong order produces an index where every chunk is filed under its
  7| //! neighbour's vector, retrieval that is confidently irrelevant, and no error
  8| //! anywhere.
  9| 
 10| use super::*;
 11| 
 12| fn signature(dims: usize) -> EmbedSignature {
 13|     EmbedSignature {
 14|         provider: "openrouter".into(),
 15|         model: "openai/text-embedding-3-small".into(),
 16|         dims,
 17|     }
 18| }
 19| 
 20| fn body(rows: &[(usize, Vec<f32>)], usage: &str) -> String {
 21|     let data: Vec<String> = rows
 22|         .iter()
 23|         .map(|(index, embedding)| {
 24|             format!(
 25|                 r#"{{"object":"embedding","index":{index},"embedding":{}}}"#,
 26|                 serde_json::to_string(embedding).expect("serialises")
 27|             )
 28|         })
 29|         .collect();
 30|     format!(r#"{{"object":"list","data":[{}]{usage}}}"#, data.join(","))
 31| }
 32| 
 33| #[test]
 34| fn vectors_come_back_in_input_order_not_arrival_order() {
 35|     // The gateway is under no obligation to return rows in order, and several
 36|     // upstreams do not. Trusting arrival order would put each vector on the
 37|     // wrong chunk — silently, and undetectably from the retrieval layer.
 38|     let raw = body(
 39|         &[
 40|             (2, vec![0.3, 0.3]),
 41|             (0, vec![0.1, 0.1]),
 42|             (1, vec![0.2, 0.2]),
 43|         ],
 44|         "",
 45|     );
 46|     let parsed = parse(&raw).expect("parses");
 47|     let vectors = parsed.vectors(3, 2).expect("orders");
 48| 
 49|     assert_eq!(vectors[0], vec![0.1, 0.1]);
 50|     assert_eq!(vectors[1], vec![0.2, 0.2]);
 51|     assert_eq!(vectors[2], vec![0.3, 0.3]);
 52| }
 53| 
 54| #[test]
 55| fn a_duplicated_index_is_refused_rather_than_silently_reordered() {
 56|     // Two rows claiming index 0 sort into a stable but arbitrary order, and one
 57|     // input would end up with no vector of its own.
 58|     let raw = body(&[(0, vec![0.1, 0.1]), (0, vec![0.2, 0.2])], "");
 59|     let parsed = parse(&raw).expect("parses");
 60|     let err = parsed.vectors(2, 2).expect_err("refuses");
 61|     assert!(err.to_string().contains("index"), "{err}");
 62| }
 63| 
 64| #[test]
 65| fn a_short_response_is_refused() {
 66|     // One vector for two chunks: whichever chunk lost is indexed against
 67|     // nothing, and the caller cannot tell which.
 68|     let raw = body(&[(0, vec![0.1, 0.1])], "");
 69|     let parsed = parse(&raw).expect("parses");
 70|     let err = parsed.vectors(2, 2).expect_err("refuses");
 71|     assert!(err.to_string().contains("for 2 inputs"), "{err}");
 72| }
 73| 
 74| #[test]
 75| fn a_vector_of_the_wrong_width_is_refused() {
 76|     // The signature is the index partition key and the search index declares
 77|     // the width at creation. A vector of another width means the configured
 78|     // signature and the model disagree, and the whole index would be built
 79|     // against the wrong one.
 80|     let raw = body(&[(0, vec![0.1, 0.2, 0.3])], "");
 81|     let parsed = parse(&raw).expect("parses");
 82|     let err = parsed.vectors(1, 2).expect_err("refuses");
 83|     assert!(err.to_string().contains("dimensional"), "{err}");
 84| }
 85| 
 86| #[test]
 87| fn a_reported_cost_is_preferred_over_the_local_table() {
 88|     // The gateway is quoting what it billed, including routing markup. The
 89|     // local table is hand-maintained and goes stale silently.
 90|     let usage = r#","usage":{"prompt_tokens":11,"total_tokens":11,"cost":0.00000022}"#;
 91|     let parsed = parse(&body(&[(0, vec![0.1, 0.2])], usage)).expect("parses");
 92|     let reported = parsed.usage.as_ref().expect("usage");
 93| 
 94|     let embedded = Embedded::charged(
 95|         reported.prompt_tokens.max(reported.total_tokens),
 96|         reported.cost.expect("cost"),
 97|     );
 98| 
 99|     assert_eq!(embedded.usage.embed_tokens, 11);
100|     assert!(
101|         (embedded.usage.cost_usd - 0.00000022).abs() < f64::EPSILON,
102|         "{}",
103|         embedded.usage.cost_usd
104|     );
105| }
106| 
107| #[test]
108| fn a_response_without_a_cost_still_uses_the_real_token_count() {
109|     // Tokens but no price: the count is authoritative even when the price is
110|     // not, so it must not fall all the way back to estimating both.
111|     let usage = r#","usage":{"prompt_tokens":97,"total_tokens":97}"#;
112|     let parsed = parse(&body(&[(0, vec![0.1, 0.2])], usage)).expect("parses");
113|     let reported = parsed.usage.as_ref().expect("usage");
114| 
115|     assert!(reported.cost.is_none());
116|     let embedded = Embedded::metered(
117|         &signature(2),
118|         reported.prompt_tokens.max(reported.total_tokens),
119|         vec![vec![0.1, 0.2]],
120|     );
121|     assert_eq!(embedded.usage.embed_tokens, 97);
122| }
123| 
124| #[test]
125| fn a_response_with_no_usage_at_all_still_parses() {
126|     // Degrading to an estimate is correct here; failing the call because the
