 1| //! Where a model-produced finding is allowed to point.
 2| //!
 3| //! Two rules, and the difference between them is the whole module:
 4| //!
 5| //! - A **file-scoped** lane (`critique`, `security`, `tests`) reports about
 6| //!   code. Its findings must sit on a line this pull request changed, and one
 7| //!   that does not is dropped. Posting a comment on unrelated code is the
 8| //!   fastest way for a review bot to lose a team's trust.
 9| //! - A **pull-request-scoped** lane (`commits`, `description`) reports about
10| //!   things that have no line at all: a commit message, an empty body. Dropping
11| //!   those would silence the lane entirely, so instead the anchor is *removed*
12| //!   and the finding becomes summary-only — `apply` posts an inline comment
13| //!   only for a finding that has a line, and renders the rest in the summary
14| //!   table.
15| 
16| use crate::evidence::diff::FileDiff;
17| use crate::findings::types::Finding;
18| 
19| /// Whether a finding points at a line this pull request actually changed.
20| ///
21| /// A finding marked `late` is exempt — it is explicitly about untouched code,
22| /// and the model had to justify that separately.
23| pub fn anchored_in_diff(finding: &Finding, diffs: &[FileDiff]) -> bool {
24|     if finding.late {
25|         return diffs.iter().any(|d| d.path == finding.path);
26|     }
27| 
28|     let Some((start, end)) = finding.range() else {
29|         return false;
30|     };
31|     diffs
32|         .iter()
33|         .find(|d| d.path == finding.path)
34|         .is_some_and(|d| d.touches_range(start, end))
35| }
36| 
37| /// Demote a finding that does not sit on a changed line to summary-only.
38| ///
39| /// Used by the lanes whose subject matter has no line number. Keeping the bad
40| /// anchor would put a comment on unrelated code; dropping the finding would
41| /// throw away the lane's actual job.
42| pub fn demote_unanchored(mut finding: Finding, diffs: &[FileDiff]) -> Finding {
43|     if !anchored_in_diff(&finding, diffs) {
44|         finding.line = None;
45|         finding.end_line = None;
46|     }
47|     finding
48| }
