  1| //! The `critique` lane: correctness of the diff.
  2| //!
  3| //! The first lane, and the template for the rest. Its shape is the point:
  4| //!
  5| //! 1. Decide whether there is anything to review at all, before spending a
  6| //!    token.
  7| //! 2. Build the prompt in cache-friendly layers.
  8| //! 3. Ask for structured output; refuse to parse prose.
  9| //! 4. Place every finding by the code it quoted, not by a number it guessed.
 10| //! 5. Drop the findings the diff disproves.
 11| //!
 12| //! Steps 4 and 5 are the noise control, and they pull in opposite directions on
 13| //! purpose. Step 4 (`src/position`) exists because the old rule — the model
 14| //! emits a line number, and anything outside the diff is dropped — threw away
 15| //! good findings for bad arithmetic. Step 5 (`src/falsify`) exists because
 16| //! keeping more findings is only an improvement if the wrong ones still go, and
 17| //! it removes only what the diff *disproves*, never what it merely cannot
 18| //! confirm.
 19| //!
 20| //! A finding that cannot be placed is no longer dropped. It loses its line and
 21| //! is rendered into the check-run summary instead of posted inline, which is
 22| //! the honest outcome: the review found something and could not say exactly
 23| //! where.
 24| 
 25| use std::sync::Arc;
 26| 
 27| use async_trait::async_trait;
 28| 
 29| use crate::config::types::LaneId;
 30| use crate::error::Result;
 31| use crate::evidence::diff::FileDiff;
 32| use crate::evidence::replay;
 33| use crate::falsify::Falsifier;
 34| use crate::harness::prompt::{self, PromptInputs};
 35| use crate::harness::schema::{self, RawFinding};
 36| use crate::lanes::{Lane, LaneInput, LaneOutcome};
 37| use crate::ports::model::{Message, Model, ModelRequest, Spend};
 38| use crate::position::{PositionRequest, Positioner, Resolution, Unanchored};
 39| 
 40| /// The correctness lane.
 41| pub struct Critique {
 42|     model: Arc<dyn Model>,
 43| }
 44| 
 45| impl Critique {
 46|     /// Build the lane over `model`.
 47|     pub fn new(model: Arc<dyn Model>) -> Self {
 48|         Self { model }
 49|     }
 50| }
 51| 
 52| #[async_trait]
 53| impl Lane for Critique {
 54|     fn id(&self) -> LaneId {
 55|         LaneId::Critique
 56|     }
 57| 
 58|     async fn run(&self, input: LaneInput<'_>) -> Result<LaneOutcome> {
 59|         // Cheapest possible check first. A pull request that only deletes
 60|         // files, or only touches ignored paths, has nothing for this lane, and
 61|         // asking a model to confirm that is money for a foregone conclusion.
 62|         if !input.has_reviewable_content() {
 63|             return Ok(LaneOutcome::skipped(
 64|                 "No added or modified lines to review.",
 65|             ));
 66|         }
 67| 
 68|         if input.pull_request.draft && !input.config.review.draft_prs {
 69|             return Ok(LaneOutcome::skipped(
 70|                 "Draft pull request; set `review.draft_prs = true` to review drafts.",
 71|             ));
 72|         }
 73| 
