207| /// The head-revision range a finding may be posted against, if any.
208| ///
209| /// One rule: the range has to be inside a hunk, because that is exactly what
210| /// GitHub will accept an inline comment on. That is deliberately wider than
211| /// *the lines this pull request changed* — a finding that quotes a context
212| /// line inside the hunk is about the change too, and the quotation is evidence
213| /// the model really did read that line rather than guess at it. It is also
214| /// deliberately narrower than *anywhere in the file*: a finding that resolved
215| /// through the whole-file fallback to code the diff never showed cannot be
216| /// posted inline, so it goes in the summary rather than being thrown away.
217| fn postable_range(raw: &RawFinding, diff: &FileDiff, resolution: Resolution) -> Option<(u64, u64)> {
218|     let (start, end) = match resolution {
219|         Resolution::Anchored(anchor) => (anchor.start, anchor.end),
220|         // The migration path: a model still answering with the old schema gets
221|         // its line number honoured, because there is no quotation to place and
222|         // its number is better than nothing.
223|         Resolution::Unanchored(Unanchored::NoSnippet) => {
224|             let line = raw.line?;
225|             (line, raw.end_line.unwrap_or(line))
226|         }
227|         Resolution::Unanchored(Unanchored::NoMatch) => return None,
228|     };
229| 
230|     diff.within_hunk(start, end).then_some((start, end))
231| }
