115|         let spend = Spend::of(&response);
116|         let parsed = schema::parse(LaneId::Critique, response.value)?;
117| 
118|         let mut spend = spend;
119|         let positioner = Positioner::new(self.model.as_ref(), input.config);
120| 
121|         let mut findings = Vec::new();
122|         let mut unanchored = 0usize;
123|         let mut discarded = 0usize;
124| 
125|         for raw in parsed.findings {
126|             // A file this pull request never touched is still dropped outright.
127|             // There is nothing to anchor against and nothing this author did.
128|             let Some(diff) = input.diffs.iter().find(|d| d.path == raw.path) else {
129|                 discarded += 1;
130|                 continue;
131|             };
132| 
133|             // Budget check: relocation can make one model call per unresolvable
134|             // finding, so enforce the limit inside the loop before escalating to
135|             // stage 3. Do not wait until the lane finishes.
136|             if spend.cost_usd() > input.config.models.budget_usd_per_pr {
137|                 return Err(crate::error::Error::Budget {
138|                     spent: spend.cost_usd(),
139|                     limit: input.config.models.budget_usd_per_pr,
140|                 });
141|             }
142| 
143|             let comment = format!("{}\n\n{}", raw.title, raw.body);
144|             let snippet = raw.existing_code.clone().unwrap_or_default();
145|             let resolution = positioner
146|                 .resolve(
147|                     PositionRequest {
148|                         snippet: &snippet,
149|                         diff: Some(diff),
150|                         file: input.file_contents.get(&raw.path).map(String::as_str),
151|                         comment: &comment,
152|                         // Relocation and falsification need the complete
153|                         // current evidence even when that evidence was placed
154|                         // in the cacheable prompt prefix on an initial run.
155|                         rendered_diff: &evidence,
156|                     },
157|                     &mut spend,
158|                 )
159|                 .await;
160| 
161|             let range = postable_range(&raw, diff, resolution);
162|             if range.is_none() {
163|                 unanchored += 1;
164|             }
165| 
166|             let mut finding = raw.into_finding(LaneId::Critique);
167|             finding.line = range.map(|(start, _)| start);
168|             finding.end_line = range.and_then(|(start, end)| (end > start).then_some(end));
169| 
170|             // Postability is wider than the changed-line set, so a finding can
171|             // now land on a context line the pull request never touched. That
172|             // is a deliberate widening, but it must not be a silent one: the
173|             // noise rule is "introduced by this pull request", and a reader has
174|             // to be able to tell when a finding is not. Marking it `late` is
175|             // what puts the pre-existing badge on it in the summary.
176|             if let Some((start, end)) = range
177|                 && !diff.touches_range(start, end)
178|             {
179|                 finding.late = true;
180|             }
181| 
182|             findings.push(finding);
183|         }
184| 
185|         // Step 5, on the findings that survived positioning. It sees only the
186|         // diff, and it can only remove.
187|         let filtered = Falsifier::new(self.model.as_ref(), input.config)
188|             .filter(LaneId::Critique, findings, &evidence)
189|             .await;
190|         spend.merge(filtered.spend);
191| 
192|         Ok(LaneOutcome {
193|             summary: summarise(
194|                 parsed.summary.trim(),
195|                 unanchored,
196|                 discarded,
197|                 filtered.rejected.len(),
198|             ),
199|             findings: filtered.findings,
200|             resolved: parsed.resolved,
201|             spend,
202|             skipped: None,
203|         })
204|     }
205| }
