118| /// The deterministic verdict on a pull request with no description.
119| fn empty_body_outcome(pr: &PullRequest, files: usize) -> LaneOutcome {
120|     let suggestion = suggested_body(pr, files);
121|     LaneOutcome {
122|         summary: "The pull request has no description.".into(),
123|         findings: vec![Finding {
124|             lane: LaneId::Description,
125|             severity: Severity::High,
126|             // Certain: this is a string length, not a judgement.
127|             confidence: 1.0,
128|             // Not a file. The renderer prints the path verbatim, and an empty
129|             // string renders as an empty code span; naming the subject is
130|             // clearer than pretending the finding belongs to some file.
131|             path: DESCRIPTION_SUBJECT.into(),
132|             line: None,
133|             end_line: None,
134|             rule: "empty-description".into(),
135|             title: "Describe what this pull request changes and why".into(),
136|             body: "The body is empty, so a reviewer has to reconstruct the intent from the diff. \
137|                    Say what changed, why, and how it was verified."
138|                 .into(),
139|             suggestion: Some(suggestion),
140|             late: false,
141|             identity: None,
142|         }],
143|         resolved: vec![],
144|         spend: Default::default(),
145|         skipped: None,
146|     }
147| }
