149| /// A skeleton body the author can fill in.
150| ///
151| /// Deliberately a template rather than a guess at intent: inventing a summary
152| /// of someone else's change and presenting it as their description is how a
153| /// bot puts words in an author's mouth.
154| fn suggested_body(pr: &PullRequest, files: usize) -> String {
155|     format!(
156|         "## What changed\n\n{}\n\n## Why\n\n_Why this change is needed._\n\n\
157|          ## How it was verified\n\n_Tests run, or what was checked by hand._\n\n\
158|          (Touches {files} file{}.)",
159|         pr.title.trim(),
160|         if files == 1 { "" } else { "s" }
161|     )
162| }
