116| /// The results of a fan-out, successes and failures kept apart.
117| #[derive(Debug, Default)]
118| pub struct FanOut {
119|     /// One entry per file that was reviewed.
120|     pub reviews: Vec<FileReview>,
121|     /// The files whose review failed, with why.
122|     pub failures: Vec<(String, Error)>,
123| }
124| 
125| impl FanOut {
126|     /// Fold the per-file results into one lane outcome.
127|     ///
128|     /// The summary reports the failures explicitly. A partial review that reads
129|     /// like a complete one is worse than no review at all, because a human
130|     /// stops looking.
131|     pub fn into_outcome(self) -> LaneOutcome {
132|         let reviewed = self.reviews.len();
133|         let mut findings = Vec::new();
134|         let mut resolved = Vec::new();
135|         let mut spend = Spend::default();
136|         let mut only_summary = None;
137| 
138|         for review in self.reviews {
139|             spend.merge(review.spend);
140|             findings.extend(review.findings);
141|             resolved.extend(review.resolved);
142|             only_summary = Some(review.summary);
143|         }
144| 
145|         // One file is the common case for a small pull request, and its own
146|         // sentence says more than a count would.
147|         let mut summary = match (reviewed, only_summary) {
148|             (1, Some(single)) if !single.trim().is_empty() => single.trim().to_string(),
149|             _ => format!(
150|                 "Reviewed {reviewed} file{}; {} finding{}.",
151|                 plural(reviewed),
152|                 findings.len(),
153|                 plural(findings.len())
154|             ),
155|         };
156| 
157|         if !self.failures.is_empty() {
158|             let names: Vec<&str> = self
159|                 .failures
160|                 .iter()
161|                 .map(|(path, _)| path.as_str())
162|                 .collect();
163|             summary.push_str(&format!(
164|                 " {} file{} could not be reviewed: {}.",
165|                 self.failures.len(),
166|                 plural(self.failures.len()),
167|                 names.join(", ")
168|             ));
169|         }
170| 
171|         let skipped = (reviewed == 0 && !self.failures.is_empty())
172|             .then(|| "No files could be reviewed; see the listed provider failures.".to_string());
173|         LaneOutcome {
174|             summary,
175|             findings,
176|             resolved,
177|             spend,
178|             skipped,
179|         }
180|     }
181| }
182| 
183| fn plural(count: usize) -> &'static str {
184|     if count == 1 { "" } else { "s" }
185| }
