482| /// Bits-per-character a value must carry before the heuristic will flag it.
483| ///
484| /// Set from measurement, not intuition: a 32-character base64 credential lands
485| /// around 4.6–5.0, while `snake_case_identifiers_like_this` sits near 3.7.
486| /// Short strings with diverse characters score higher than their information
487| /// content deserves, which is why [`is_opaque_token`] and a length floor guard
488| /// this check rather than the other way round.
489| const ENTROPY_THRESHOLD: f64 = 4.2;
490| 
491| /// Shannon entropy in bits per character.
492| fn shannon_entropy(value: &str) -> f64 {
493|     if value.is_empty() {
494|         return 0.0;
495|     }
496| 
497|     let mut counts = [0usize; 256];
498|     let mut total = 0usize;
499|     for byte in value.bytes() {
500|         counts[byte as usize] += 1;
501|         total += 1;
502|     }
503| 
504|     let total = total as f64;
505|     counts
506|         .iter()
507|         .filter(|&&count| count > 0)
508|         .map(|&count| {
509|             let p = count as f64 / total;
510|             -p * p.log2()
511|         })
512|         .sum()
513| }
