101|     /// A short-lived JWT proving who the app is.
102|     pub fn app_jwt(&self) -> Result<String> {
103|         let now = SystemTime::now()
104|             .duration_since(UNIX_EPOCH)
105|             .map_err(|err| Error::Forge(err.to_string()))?
106|             .as_secs();
