121|     pub async fn installation_token(&self, installation: u64) -> Result<String> {
122|         if let Some(cached) = self.cache.lock().await.get(&installation)
123|             && cached.expires > SystemTime::now() + RENEW_MARGIN
124|         {
125|             return Ok(cached.token.clone());
126|         }
127| 
128|         let jwt = self.app_jwt()?;
