169| /// Parse GitHub's RFC 3339 expiry into a `SystemTime`.
170| ///
171| /// Hand-rolled rather than pulling in a date library for one field. A value we
172| /// cannot parse yields `None`, and the caller falls back to an hour — which is
173| /// what GitHub issues anyway, so the failure mode is a slightly early renewal.
174| fn parse_expiry(text: &str) -> Option<SystemTime> {
175|     let (date, rest) = text.split_once('T')?;
176|     let time = rest.trim_end_matches('Z');
177| 
178|     let mut date = date.split('-');
179|     let year: i64 = date.next()?.parse().ok()?;
180|     let month: i64 = date.next()?.parse().ok()?;
181|     let day: i64 = date.next()?.parse().ok()?;
182| 
183|     let mut time = time.split(':');
184|     let hour: i64 = time.next()?.parse().ok()?;
185|     let minute: i64 = time.next()?.parse().ok()?;
186|     let second: i64 = time.next().unwrap_or("0").split('.').next()?.parse().ok()?;
187| 
188|     // Days since the Unix epoch, by the civil-from-days algorithm.
189|     let year = if month <= 2 { year - 1 } else { year };
190|     let era = if year >= 0 { year } else { year - 399 } / 400;
191|     let year_of_era = year - era * 400;
192|     let day_of_year = (153 * (if month > 2 { month - 3 } else { month + 9 }) + 2) / 5 + day - 1;
193|     let day_of_era = year_of_era * 365 + year_of_era / 4 - year_of_era / 100 + day_of_year;
194|     let days = era * 146_097 + day_of_era - 719_468;
195| 
196|     let seconds = days * 86_400 + hour * 3_600 + minute * 60 + second;
197|     (seconds > 0).then(|| UNIX_EPOCH + Duration::from_secs(seconds as u64))
198| }
